-- Автосгенерировано из присланных вопросов. Вставляет 26 вопросов
-- в пробник "Пробник 2026" (найденный по названию), с категориями и
-- правильными ответами. Выполнять ПОСЛЕ full-reset.sql.

with t as (select id from practice_tests where title = 'Пробник 2026' limit 1)
insert into questions (test_id, prompt, options, correct_option_ids, category, sort_order)
select t.id, v.prompt, v.options::jsonb, v.correct_option_ids::jsonb, v.category, v.sort_order
from t, (values
  ($p0$Die FunBike GmbH mit Sitz in Wien möchte kurzfristig ihren Cashflow erhöhen. Mit welchen Maßnahmen ist dies für diese Gesellschaft möglich?$p0$, $o0$[{"id":"a","text":"nimmt einen Bankkredit über 100 000 EUR auf"},{"id":"b","text":"kauft eine benötigte Maschine um 50 000 EUR, die bisher um 1 000 EUR pro Monat gemietet wurde"},{"id":"c","text":"emittiert Aktien"},{"id":"d","text":"nimmt einen weiteren Gesellschafter auf, der eine zusätzliche Kapitaleinlage leistet"},{"id":"e","text":"gewährt kein Zahlungsziel mehr. Alle Kund*innen müssen sofort bezahlen."}]$o0$, $c0$["a","d","e"]$c0$, $g0$Понимание экономики$g0$, 1),
  ($p1$Nachstehend sehen Sie die Bilanz der FunBike GmbH per 31.12.20xx. Welche der folgenden Aussagen zu dieser Bilanz ist/sind richtig?$p1$, $o1$[{"id":"a","text":"Wenn die FunBike GmbH Aktien kauft und damit die Finanzanlagen erhöht, steigt auch ihr Eigenkapital."},{"id":"b","text":"Wenn die Laufzeit der Bankkredite zehn Jahre beträgt, ist das langfristige Vermögen auch langfristig finanziert."},{"id":"c","text":"Die Vorräte betragen mehr als die Hälfte der Bilanzsumme."},{"id":"d","text":"Die Bilanzposition mit der höchsten Liquidität ist „Bankguthaben und Barbestand\"."},{"id":"e","text":"Die FunBike GmbH bezahlt alle ihre Rechnungen sofort."}]$o1$, $c1$["b","c","d"]$c1$, $g1$Понимание экономики$g1$, 2),
  ($p2$Welche der folgenden Aussagen zum Zusammenhang von Wirtschaft, Umwelt und Politik ist/sind richtig?$p2$, $o2$[{"id":"a","text":"Wirtschaftliche Akteur*innen beziehen Inputs aus der Natur (z.B. natürliche Ressourcen) und geben Outputs (z.B. Abfall, Emissionen) an die Natur zurück."},{"id":"b","text":"Die Einhaltung von Erdsystemgrenzen ist wichtig für die Widerstandsfähigkeit von Ökosystemen."},{"id":"c","text":"Nachhaltigkeit beschreibt ein Ökosystem, mit dem alle menschlichen Bedürfnisse befriedigt werden können."},{"id":"d","text":"Das Konzept der schwachen Nachhaltigkeit beruht auf dem Drei-Säulen-Modell: Ökologie, Soziales und Ökonomie sind gleichwertige Säulen für wirtschaftliche Entwicklung."},{"id":"e","text":"In den letzten 30 Jahren ist es nur den reichen Ländern gelungen, die nachhaltigen Entwicklungsziele (SDGs) zu erreichen."}]$o2$, $c2$["a","b","d"]$c2$, $g2$Понимание экономики$g2$, 3),
  ($p3$Welche der folgenden Aussagen zur Disziplin der Wirtschaftsinformatik ist/sind richtig?$p3$, $o3$[{"id":"a","text":"Die Wirtschaftsinformatik beschäftigt sich vorrangig mit betriebswirtschaftlichen Themenstellungen."},{"id":"b","text":"Es gibt technische, biologische und verhaltenswissenschaftliche Perspektiven des interdisziplinären Fachs der Wirtschaftsinformatik."},{"id":"c","text":"Aus technischer Perspektive gibt es unter anderem die Fächer Produktionsmanagement, Informatik und Data Science."},{"id":"d","text":"Gegenstand der Wirtschaftsinformatik sind Informationssysteme in Wirtschaft, Verwaltung und dem privaten Bereich."},{"id":"e","text":"Die Wirtschaftsinformatik kann als übergreifendes Fach zwischen Politikwissenschaft und Informatik betrachtet werden."}]$o3$, $c3$["c","d"]$c3$, $g3$Понимание экономики$g3$, 4),
  ($p4$Welche der folgenden Aussagen zu Wirtschaft als Teil der Gesellschaft und der Natur ist/sind richtig?$p4$, $o4$[{"id":"a","text":"Die Wirtschaft ist eingebettet in ein gesellschaftliches Umfeld; wirtschaftliche Aktivitäten sind aber von Umweltveränderungen unabhängig."},{"id":"b","text":"Eine Kreislaufwirtschaft minimiert Abfälle und schont Ressourcen, z.B. durch Wiederverwerten, Recycling und Reparieren."},{"id":"c","text":"Über den Zeitraum von 1800 bis 2024 haben die Länder des Globalen Südens (v.a. Indien und China) die meisten Emissionen ausgestoßen."},{"id":"d","text":"Das reichste Prozent der Weltbevölkerung ist für doppelt so viele Kohlendioxidemissionen verantwortlich wie die ärmsten 50%."},{"id":"e","text":"Klimawandel ist eine von mehreren Erdsystemgrenzen, die schon überschritten wurden."}]$o4$, $c4$["b","d","e"]$c4$, $g4$Понимание экономики$g4$, 5),
  ($p5$Welche der folgenden Aussagen zum Bruttoinlandsprodukt (BIP) ist/sind richtig?$p5$, $o5$[{"id":"a","text":"Das BIP wird zur Bestimmung des Wirtschaftswachstums herangezogen."},{"id":"b","text":"Wenn das BIP sinkt, ist die Wirtschaft gewachsen."},{"id":"c","text":"Das reale BIP ist das um Preisniveauänderungen bereinigte BIP."},{"id":"d","text":"Das BIP umfasst alle Größen, die als Wirtschaftsleistung angesehen werden können, also auch unentgeltliche Pflege- und Sorgearbeit."},{"id":"e","text":"Das BIP basiert auf dem Inländerkonzept und ist der Wert aller Waren und Dienstleistungen, die in einer bestimmten Zeitperiode von Inländern für den Endverbrauch erzeugt werden."}]$o5$, $c5$["a","c"]$c5$, $g5$Понимание экономики$g5$, 6),
  ($p6$Felix möchte in Österreich ein Unternehmen gründen und allein die Geschäfte führen. Bei welcher/welchen der folgenden Gesellschaftsformen ist das möglich?$p6$, $o6$[{"id":"a","text":"Gesellschaft mit beschränkter Haftung (GmbH)"},{"id":"b","text":"Das ins Firmenbuch eingetragene Einzelunternehmen"},{"id":"c","text":"Offene Handelsgesellschaft (OHG)"},{"id":"d","text":"Kommanditgesellschaft (KG)"},{"id":"e","text":"Flexible Kapitalgesellschaft (FlexKapG)"}]$o6$, $c6$["a","e"]$c6$, $g6$Понимание экономики$g6$, 7),
  ($p7$Welche der folgenden Aussagen zum Internet und dem WWW ist/sind richtig?$p7$, $o7$[{"id":"a","text":"Das Internet ist ein Netzwerk, über welches man Daten versenden und empfangen kann."},{"id":"b","text":"Das World Wide Web (kurz WWW) baut auf der Infrastruktur des Internets auf."},{"id":"c","text":"Tim Berners-Lee hat im Jahr 1989, während seiner Arbeit am CERN, das Internet erfunden."},{"id":"d","text":"Das Internet verwendet unter anderem das „Identification Protocol (IP)\" um eindeutig über eine IP-Adresse Personen in einem Netzwerk zu identifizieren."},{"id":"e","text":"Das Internet und das WWW basieren auf einem einzigen gemeinsamen Protokoll."}]$o7$, $c7$["a","b"]$c7$, $g7$Понимание экономики$g7$, 8),
  ($p8$Welche der folgenden Aussagen über Inflation ist/sind richtig?$p8$, $o8$[{"id":"a","text":"Wenn das allgemeine Preisniveau steigt, weil die Preise für viele Waren und Dienstleistungen erhöht werden, spricht man von Inflation."},{"id":"b","text":"Die Kaufkraft steigt durch Inflation."},{"id":"c","text":"Um Inflationsraten zu reduzieren, kann die Zentralbank eine Leitzinssenkung durchführen."},{"id":"d","text":"Inflation kann durch steigende Kosten, z.B. durch einen Anstieg der Energiepreise, entstehen."},{"id":"e","text":"Die Europäische Zentralbank (EZB) strebt mittelfristig eine Inflationsrate von 2% pro Jahr an."}]$o8$, $c8$["a","d","e"]$c8$, $g8$Понимание экономики$g8$, 9),
  ($p9$Welche der folgenden Aussagen ist/sind richtig?$p9$, $o9$[{"id":"a","text":"Aktien und Anleihen können nur zum Zeitpunkt ihrer Emission gekauft werden."},{"id":"b","text":"Sowohl Aktien als auch Anleihen sind Wertpapiere, durch die Käufer am Eigenkapital eines Unternehmens beteiligt sind."},{"id":"c","text":"Sowohl Aktien- als auch Anleihenkapital muss ein Unternehmen an einem bestimmten Stichtag zurückzahlen."},{"id":"d","text":"Zinsen für Anleihenkapital muss ein Unternehmen bezahlen, auch wenn es keine Gewinne macht."},{"id":"e","text":"Dividenden für Aktienkapital muss ein Unternehmen ausschütten, auch wenn es keine Gewinne macht."}]$o9$, $c9$["d"]$c9$, $g9$Понимание экономики$g9$, 10),
  ($p10$Welche der folgenden Aussagen über "Wirtschaften" ist/sind richtig?$p10$, $o10$[{"id":"a","text":"Durch das Zusammentreffen von Angebot und Nachfrage auf Märkten kommt es zur Preisbildung."},{"id":"b","text":"Die Ressourcen, über die Haushalte und Unternehmen jeweils verfügen, sind knapp, deshalb muss mit ihnen gewirtschaftet werden."},{"id":"c","text":"Die Entscheidungen über den Einsatz der begrenzten Ressourcen stehen im Mittelpunkt des Wirtschaftens."},{"id":"d","text":"Opportunitätskosten sind entgangene Erträge oder nicht erzielter Nutzen einer Handlungsalternative, auf die man zugunsten einer anderen Handlungsalternative verzichtet hat."},{"id":"e","text":"Die Nachfrage stellt die gesamte Menge eines Gutes dar, die Wirtschaftsteilnehmer*innen kaufen wollen und können."}]$o10$, $c10$["a","b","c","d","e"]$c10$, $g10$Понимание экономики$g10$, 11),
  ($p11$Welche der folgenden Aussagen zum Thema der digitalen Transformation ist/sind richtig?$p11$, $o11$[{"id":"a","text":"Geschäftsprozesse können durch Informationssysteme digital unterstützt, erweitert und gesteuert werden."},{"id":"b","text":"Durch die Anwendung digitaler Informations- und Kommunikationstechnologie kann digitale Transformation stattfinden."},{"id":"c","text":"Man spricht oft von drei Anwendungsgebieten der Digitalisierung: 1. Mobilgeräte, 2. Server, 3. Cloudbasierte Rechner."},{"id":"d","text":"Digitale Transformation hat keinen Einfluss auf das Informationssystem eines Unternehmens."},{"id":"e","text":"Man spricht oft von drei Dimensionen der Digitalisierung: 1. Externer Fokus, 2. Interner Fokus, 3. Output (Ergebnis)."}]$o11$, $c11$["a","b","e"]$c11$, $g11$Понимание экономики$g11$, 12),
  ($p12$Warum schätzen viele Deutsche ihr Einkommen falsch ein?$p12$, $o12$[{"id":"a","text":"Sie vergleichen sich nur mit Personen aus ihrer eigenen sozialen Schicht."},{"id":"b","text":"Sie haben keinen Zugang zu genauen Einkommensstatistiken."},{"id":"c","text":"Sie überschätzen das eigene Einkommen."},{"id":"d","text":"Sie orientieren sich an Durchschnittseinkommen."},{"id":"e","text":"Sie ignorieren die Ungleichheit in der Vermögensverteilung."}]$o12$, $c12$["a"]$c12$, $g12$Понимание немецкого текста$g12$, 13),
  ($p13$Wer wird laut dem Text explizit als reich oder wohlhabend beschrieben, basierend auf Einkommen, Vermögen oder gesellschaftlicher Stellung?$p13$, $o13$[{"id":"a","text":"Der durchschnittliche Leser/die durchschnittliche Leserin der Süddeutschen Zeitung."},{"id":"b","text":"Personen, die eine Immobilie besitzen."},{"id":"c","text":"Personen, die Elterngeld beziehen."},{"id":"d","text":"Personen, die ein E-Auto besitzen."},{"id":"e","text":"Personen mit einem Vermögen von mehr als 300 000 Euro."}]$o13$, $c13$["a","b"]$c13$, $g13$Понимание немецкого текста$g13$, 14),
  ($p14$Was versteht man unter "Mittelschicht" laut Bertelsmann Stiftung?$p14$, $o14$[{"id":"a","text":"Ein Vermögen von mindestens 500 000 Euro."},{"id":"b","text":"Einkommen zwischen 75 und 200 Prozent des nationalen Medians."},{"id":"c","text":"Die Einschätzung des eigenen Einkommens zwischen 6 und 7 auf einer zehnteiligen Skala."},{"id":"d","text":"Einkommen, das maximal 19 Prozent vom Durchschnitt abweicht."},{"id":"e","text":"Verfügbares Einkommen zwischen 1 500 und 4 000 Euro bei Alleinstehenden."}]$o14$, $c14$["b","e"]$c14$, $g14$Понимание немецкого текста$g14$, 15),
  ($p15$Welche Aussagen macht der Text über die Auswirkungen des Elterngeldes?$p15$, $o15$[{"id":"a","text":"Es wird hauptsächlich von Gutverdiener*innen genutzt."},{"id":"b","text":"Es soll Lohnausfälle bei Eltern ausgleichen."},{"id":"c","text":"Es wurde kürzlich vollständig abgeschafft."},{"id":"d","text":"Es wird von allen sozialen Schichten gleich stark kritisiert."},{"id":"e","text":"Es wird diskutiert, die Einkommensgrenze zu senken."}]$o15$, $c15$["b","e"]$c15$, $g15$Понимание немецкого текста$g15$, 16),
  ($p16$Welche Folgen hat die Fehleinschätzung des eigenen Einkommens laut Text?$p16$, $o16$[{"id":"a","text":"Politische Entscheidungen treffen nicht die Zielgruppe."},{"id":"b","text":"Wohlhabende Menschen fühlen sich benachteiligt."},{"id":"c","text":"Die Mittelschicht wächst stetig."},{"id":"d","text":"Reiche Haushalte erhalten oft zusätzliche Förderung."},{"id":"e","text":"Die Kluft zwischen Arm und Reich nimmt ab."}]$o16$, $c16$["a","d"]$c16$, $g16$Понимание немецкого текста$g16$, 17),
  ($p17$Welche Themen wurden im Text als Beispiele für Förderungen für Wohlhabende genannt?$p17$, $o17$[{"id":"a","text":"Ladestationen für E-Autos"},{"id":"b","text":"Elterngeld für hohe Einkommen"},{"id":"c","text":"Wärmepumpen-Förderungen"},{"id":"d","text":"Steuererleichterungen für Investoren"},{"id":"e","text":"Förderung für Solaranlagen"}]$o17$, $c17$["a","b","c","e"]$c17$, $g17$Понимание немецкого текста$g17$, 18),
  ($p18$Welche Aussagen zu Vermögens- und Einkommensverteilung sind korrekt?$p18$, $o18$[{"id":"a","text":"Die oberen fünf Prozent besitzen mehr als 40 Prozent des Vermögens."},{"id":"b","text":"7,9 Prozent der Deutschen haben ein hohes Einkommen."},{"id":"c","text":"Ein Nettovermögen von 500 000 Euro gehört zu den Top-Vermögen."},{"id":"d","text":"Die Mehrheit der Deutschen lebt in eigenen Immobilien."},{"id":"e","text":"Ein Einkommen von 13 000 Euro netto gehört zu den Top-1-Prozent."}]$o18$, $c18$["a","b","c","e"]$c18$, $g18$Понимание немецкого текста$g18$, 19),
  ($p19$Welche Maßnahmen könnten laut Text helfen, Ungleichheit und Fehleinschätzungen zu reduzieren?$p19$, $o19$[{"id":"a","text":"Mehr Transparenz über Einkommen und Vermögen"},{"id":"b","text":"Reduktion von Politikergehältern"},{"id":"c","text":"Klarere Definitionen von sozialer Schicht"},{"id":"d","text":"Anpassung von staatlichen Förderprogrammen"},{"id":"e","text":"Einführung einer Erbschaftssteuer"}]$o19$, $c19$["a","c","d"]$c19$, $g19$Понимание немецкого текста$g19$, 20),
  ($p20$Welche Probleme entstehen laut dem Text durch eine Fehleinschätzung des eigenen Einkommens?$p20$, $o20$[{"id":"a","text":"Falsche Wahl politischer Parteien"},{"id":"b","text":"Fehlendes Verständnis für soziale Ungleichheit"},{"id":"c","text":"Keine Förderung durch den Staat für Wohlhabende"},{"id":"d","text":"Erosion der Mittelschicht"},{"id":"e","text":"Fehlende Diskussion über Vermögenssteuer"}]$o20$, $c20$["a","b"]$c20$, $g20$Понимание немецкого текста$g20$, 21),
  ($p21$Was sind laut dem Text Ursachen für die Vermögensungleichheit in Deutschland?$p21$, $o21$[{"id":"a","text":"Wenige Menschen besitzen große Vermögen."},{"id":"b","text":"Immobilienbesitz ist stark konzentriert."},{"id":"c","text":"Elterngeld wird gleichmäßig verteilt."},{"id":"d","text":"Staatliche Förderprogramme begünstigen Wohlhabende."},{"id":"e","text":"Die Mehrheit der Deutschen zahlt keine Steuern."}]$o21$, $c21$["a","b","d"]$c21$, $g21$Понимание немецкого текста$g21$, 22),
  ($p22$Marie hat ein erfolgreiches Jahr gehabt. Sie will deshalb eine große Party geben und lädt Freunde und Familie ein. Unter anderem will sie verschiedene Sorten an Kuchen bestellen und überlegt, was jede(r) gerne isst. Dabei fällt ihr ein, dass 13 ihrer Gäste sich vegan ernähren, 5 eine Laktoseintoleranz haben und 7 an einer Nussallergie leiden. Die restlichen 25 Gäste haben keine besonderen Einschränkungen bezüglich ihrer Nahrung. Marie weiß, dass unter den veganen Gästen auch 3 laktoseintolerant und 2 allergisch gegen Nüsse sind. Außerdem ist genau ein veganer Gast sowohl laktoseintolerant als auch gegen Nüsse allergisch. Von den nicht-veganen Gästen sind 2 laktoseintolerant und auch allergisch gegen Nüsse. Marie bestellt 3 verschiedene Kuchen (einen Nusskuchen, einen laktosefreien veganen Guglhupf ohne Nüsse und einen Quarkkuchen), sodass für jeden Gast mindestens eine passende Sorte dabei ist.

Drei Gäste, Anton, Meggie und Sascha, unterhalten sich:
(1): Anton sagt, dass er besonders gerne Nusskuchen isst und er sich außerdem vegan ernährt. Vor 10 Jahren hätte die Aussage aber noch nicht zugetroffen.
(2): Meggie sagt: "Ich probiere jeweils ein Stück von jeder Kuchensorte. Wenn mir eine Sorte besonders gut schmeckt, dann esse ich noch ein viertes Stück Kuchen."
(3): Sascha sagt: "Ich bin allergisch gegen Nüsse und esse daher den Guglhupf oder den Quarkkuchen."

Es wird angenommen, dass die drei nicht gelogen haben. Welche Aussage(n) folgen daraus?$p22$, $o22$[{"id":"a","text":"Es gibt insgesamt genau 3 Gäste, die laktoseintolerant sind und eine Nussallergie haben."},{"id":"b","text":"Es sind 15 Personen vegan oder laktoseintolerant."},{"id":"c","text":"Anton hat vor 10 Jahren keinen Nusskuchen gegessen und sich auch nicht vegan ernährt."},{"id":"d","text":"Wenn Meggie kein 4. Stück Kuchen isst, dann schmeckt ihr keine Sorte besonders gut."},{"id":"e","text":"Sascha isst nur eine Kuchensorte."}]$o22$, $c22$["a","b","d"]$c22$, $g22$Математика$g22$, 23),
  ($p23$Welche der folgenden Aussagen ist/sind richtig oder falsch?$p23$, $o23$[{"id":"a","text":"Wenn x die Gleichung (x²-4)/(x-2) - 5 = 5x + (2x+6)/4 - (5x-12)/3 löst, dann ist |x| > 2."},{"id":"b","text":"Es gelte a ≠ c und a ≠ b. Dann ist (a-b)/(a-c) = (c-a)/(b-a) genau dann, wenn b = c."},{"id":"c","text":"Das Produkt aller Lösungen der Gleichung x⁴ - 4x² + 3 = 0 ist 3."},{"id":"d","text":"Wenn x die Gleichung log₅(3x-2) = 4 löst und y die Gleichung 2^(2y-2) = 4^(3y-15) löst, dann gilt x - y = 200."},{"id":"e","text":"Die Gleichung √|x-4| = |a| ist genau dann erfüllt, wenn x = a² + 4."}]$o23$, $c23$["a","c"]$c23$, $g23$Математика$g23$, 24),
  ($p24$Die Konzentration eines Medikamentes im Blut einer Patientin (gemessen in mg/dL) lasse sich annähernd durch die Funktion f(t) = 12t·e^(-0.25t) beschreiben. Dabei gibt t die Zeit in Stunden ab der Einnahme des Medikamentes an. Welche der folgenden Aussagen ist/sind richtig?$p24$, $o24$[{"id":"a","text":"Zum Zeitpunkt t = 5 nimmt die Konzentration des Medikamentes im Blut der Patientin bereits ab."},{"id":"b","text":"Die höchste Konzentration des Medikamentes im Blut der Patientin wird nach weniger als 4 Stunden erreicht."},{"id":"c","text":"Die höchste Konzentration des Medikamentes im Blut der Patientin liegt bei mehr als 17.5 mg/dL."},{"id":"d","text":"Nach 24 Stunden ist die Konzentration des Medikamentes im Blut der Patientin noch immer größer als 0.65 mg/dL."},{"id":"e","text":"Die Konzentration des Medikamentes im Blut der Patientin fällt am stärksten zum Zeitpunkt t = 8 (gerundet auf ganze Stunden)."}]$o24$, $c24$["a","c","d","e"]$c24$, $g24$Математика$g24$, 25),
  ($p25$Welche der folgenden Aussagen ist/sind richtig?$p25$, $o25$[{"id":"a","text":"Wenn Marie und ihr Vater zusammen 50 Jahre alt sind und der Vater in sieben Jahren dreimal so alt sein wird, wie Marie in sieben Jahren sein wird, dann ist der Vater heute mehr als viermal so alt wie Marie."},{"id":"b","text":"Jonas und Alexandra gehen regelmäßig ins Fitnessstudio. Jonas kaufte bisher 10 Einzeleintritte und bezahlte dafür 15 EUR mehr als Alexandra, die eine ermäßigte 10er Karte genutzt hat. Sie hat dadurch 12% gespart. Dann haben beide zusammen insgesamt mehr als 237 EUR bezahlt."},{"id":"c","text":"Im Kaffeehaus Friedrich gibt es ein besonderes Angebot, bei dem drei Muffins und drei Cappucino zusammen zum Preis von zwei Muffins und zwei Cappucino konsumiert werden können. Eine Gruppe von Studierenden bestellt insgesamt 4 Muffins und 5 Cappucino. Sie nutzen dabei das Angebot und bezahlen zusammen 20.10 EUR. Ohne das Angebot hätten sie insgesamt 25.90 EUR bezahlt. Dann kostet ein einzelner Muffin 0.40 EUR mehr als ein einzelner Cappucino."},{"id":"d","text":"Ein Händler verkauft das Smartphone Smartyphon entweder für a EUR ohne Vertrag oder für 0 EUR mit einem 24-Monats-Vertrag über monatlich b EUR. Nach Ablauf der 24 Monate wäre die Gesamtsumme aller Zahlungen 480 EUR höher als der Preis ohne Vertrag. Die Differenz zwischen den Monatsbeiträgen des Vertrages und dem durchschnittlichen Preis pro Monat bei Kauf ohne Vertrag beträgt 20 EUR. Dann ist der Preis ohne Vertrag eindeutig als 1 080 EUR bestimmbar."},{"id":"e","text":"Marion hat von ihren Eltern Geld bekommen und soll davon für den nächsten Winterurlaub Handschuhe und eine Mütze kaufen. Sie sucht sich jeweils ein Produkt aus und stellt fest, dass das Geld nicht für beides reicht. Ihr fehlen genau 7 EUR. Wenn sie nur die Handschuhe kauft, bleiben ihr noch 5 EUR übrig, wenn sie nur die Mütze kauft, dann bleiben noch 8 EUR. Dann hat Marion von ihren Eltern mehr als 21 EUR bekommen."}]$o25$, $c25$["a","c"]$c25$, $g25$Математика$g25$, 26)
) as v(prompt, options, correct_option_ids, category, sort_order);
